const COSTOS_DATA  = {"todos": {"ingresos": 0.0, "asesoras": {"Sol": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Vane": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Juli": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}}, "total_comision": 0, "resultado": 0.0}, "07-2026": {"ingresos": 0, "asesoras": {"Sol": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Vane": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Juli": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}}, "total_comision": 0, "resultado": 0}, "08-2026": {"ingresos": 0, "asesoras": {"Sol": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Vane": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}, "Juli": {"fuera_cap": 0, "comision_fuera": 0, "dentro_cap": 0, "comision_dentro": 0, "total": 0}}, "total_comision": 0, "resultado": 0}};
const COMERCIALES  = ["Sol", "Vane", "Juli"];
const meses_ch     = [];
const gs100_ch     = [];
const gs200_ch     = [];
const ingr_ch      = [];
const emb_tot      = [8, 220, 30, 3, 49];
const TOTAL_C      = 310;

// ── tabs ──────────────────────────────────────────────────────────────────────
function showTab(name, btn) {
  document.querySelectorAll('.tab-content').forEach(t=>t.classList.remove('active'));
  document.querySelectorAll('.main-tab').forEach(b=>b.classList.remove('active'));
  document.getElementById('tab-'+name).classList.add('active');
  btn.classList.add('active');
  document.getElementById('period-bar-informe').style.display = name==='informe' ? 'flex' : 'none';
}

// ── helpers ───────────────────────────────────────────────────────────────────
function fmtArs(n){ return n ? '$ '+Math.round(n).toLocaleString('es-AR') : '—'; }
function fmtPct(n,t){ return t ? (n/t*100).toFixed(1)+'%' : '0%'; }
function badgeE(e){
  const m={'Lead':'badge-grey','En Contacto':'badge-blue','Cotizado':'badge-yellow','Cerrado':'badge-green','Descartado':'badge-red'};
  return `<span class="badge ${m[e]||'badge-grey'}">${e}</span>`;
}
function tagC(c){ return c==='TERRENO'?'<span class="tag-terreno">TERRENO</span>':'<span class="tag-ospif">OSPIF</span>'; }

// ── INFORME COMERCIAL: periodo filter ─────────────────────────────────────────
let periodoActual = 'todos';
function setPeriodo(p, btn) {
  periodoActual = p;
  document.querySelectorAll('#period-bar-informe .period-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  recalcInforme();
}

function recalcInforme() {
  const p = periodoActual;
  const rows = p==='todos' ? CONTACTOS : CONTACTOS.filter(c=>c.mes===p);
  const total = rows.length;
  const emb = {};
  ESTADOS_LIST.forEach(e=>{ emb[e]=rows.filter(c=>c.estado===e).length; });
  const cerr = emb['Cerrado']||0;
  const resp = (emb['En Contacto']||0)+(emb['Cotizado']||0)+cerr;
  const desc = emb['Descartado']||0;
  const ingr = rows.filter(c=>c.estado==='Cerrado').reduce((s,c)=>s+c.cuota,0);
  const gs1  = rows.filter(c=>c.estado==='Cerrado'&&c.plan==='GS100').length;
  const gs2  = rows.filter(c=>c.estado==='Cerrado'&&c.plan==='GS200').length;

  document.getElementById('kpi-total').textContent = total;
  document.getElementById('kpi-cerrados').textContent = cerr;
  document.getElementById('kpi-planes').textContent = `GS100: ${gs1} · GS200: ${gs2}`;
  document.getElementById('kpi-cierre').textContent = fmtPct(cerr,total);
  document.getElementById('kpi-respuesta').textContent = fmtPct(resp,total);
  document.getElementById('kpi-conv').textContent = (cerr+desc)?((cerr/(cerr+desc))*100).toFixed(1)+'%':'0%';
  document.getElementById('kpi-ingresos').textContent = fmtArs(ingr);
  document.getElementById('informe-period-label').textContent = p==='todos'
    ? 'KPIs — Todos los periodos' : `KPIs — ${p}`;

  // embudo
  const funnelEl = document.getElementById('funnel-container');
  funnelEl.innerHTML='';
  const widths=[100,85,70,55,55];
  ESTADOS_LIST.forEach((e,i)=>{
    const val=emb[e]||0;
    const pct=total?(val/total*100).toFixed(1)+'%':'0%';
    const d=document.createElement('div');
    d.className='funnel-step';
    d.style.cssText=`background:${COLORES_F[i]};width:${widths[i]}%;`;
    d.innerHTML=`<span style="opacity:.9;font-size:12px">${e}</span><span style="font-size:20px;font-weight:800">${val}</span><span style="font-size:11px;opacity:.8">${pct}</span>`;
    funnelEl.appendChild(d);
  });
}

// ── charts ────────────────────────────────────────────────────────────────────
if(meses_ch.length) {
  new Chart(document.getElementById('chartVentas'),{
    type:'bar',
    data:{labels:meses_ch,datasets:[
      {label:'GS100',data:gs100_ch,backgroundColor:'#42A5F5',borderRadius:4},
      {label:'GS200',data:gs200_ch,backgroundColor:'#1E8449',borderRadius:4}
    ]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{position:'top'}},scales:{x:{stacked:true},y:{stacked:true,beginAtZero:true}}}
  });
  new Chart(document.getElementById('chartIngresos'),{
    type:'line',
    data:{labels:meses_ch,datasets:[{
      label:'Ingresos/mes',data:ingr_ch,borderColor:'#1E8449',
      backgroundColor:'rgba(30,132,73,.08)',fill:true,tension:.3,
      pointRadius:5,pointBackgroundColor:'#1E8449'
    }]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>'$ '+ctx.raw.toLocaleString('es-AR')}}},
      scales:{y:{beginAtZero:true,ticks:{callback:v=>'$'+v.toLocaleString('es-AR')}}}}
  });
}

// ── seguimiento (asesoras tab) ─────────────────────────────────────────────────
function filtrarSeguimiento() {
  const fa=document.getElementById('fa-asesora').value;
  const fe=document.getElementById('fa-estado').value;
  const fc=document.getElementById('fa-canal').value;
  const fm=document.getElementById('fa-mes').value;
  const fp=document.getElementById('fa-plan').value;
  const fb=document.getElementById('fa-buscar').value.toLowerCase();
  const rows=CONTACTOS.filter(c=>
    (!fa||c.comercial===fa)&&(!fe||c.estado===fe)&&(!fc||c.canal===fc)&&
    (!fm||c.mes===fm)&&(!fp||c.plan===fp)&&(!fb||c.nombre.toLowerCase().includes(fb)));
  document.getElementById('tbody-seguimiento').innerHTML=rows.length?rows.map(c=>`
    <tr>
      <td>${c.nombre}</td><td>${c.comercial}</td><td>${tagC(c.canal)}</td>
      <td>${badgeE(c.estado)}</td><td>${c.plan||'—'}</td><td>${c.tipo||'—'}</td>
      <td>${c.grupo||'—'}</td><td class="right">${fmtArs(c.cuota)}</td>
      <td>${c.mes||'—'}</td><td>${c.lugar||'—'}</td>
      <td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--muted)">${c.obs||''}</td>
    </tr>`).join('')
    :'<tr><td colspan="11" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-seg').textContent=rows.length+' contacto'+(rows.length!==1?'s':'');
}

// ── costos P&L ─────────────────────────────────────────────────────────────────
let costosPeriodo = 'todos';
function setCostosPeriodo(p, btn) {
  costosPeriodo = p;
  document.querySelectorAll('#costos-period-btns .period-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderCostos();
}

function plRow(concepto, valor, clase='') {
  const valStr = typeof valor === 'number' ? fmtArs(valor) : valor;
  const negClass = typeof valor === 'number' && valor < 0 ? ' neg' : '';
  return `<tr class="${clase}"><td>${concepto}</td><td class="val${negClass}">${valStr}</td></tr>`;
}

function renderCostos() {
  const d = COSTOS_DATA[costosPeriodo] || COSTOS_DATA['todos'];
  const lbl = costosPeriodo==='todos' ? 'Todos los periodos' : costosPeriodo;
  document.getElementById('costos-period-label').textContent = `Estado de Resultado Comercial — ${lbl}`;

  let html = '';
  html += plRow('INGRESOS','','pl-header');
  html += plRow('Cuotas mensuales activas', d.ingresos, 'pl-sub');
  html += plRow('Total Ingresos', d.ingresos, 'pl-subtotal');

  html += plRow('COSTOS COMERCIALES','','pl-header');

  // Comisiones por asesora
  COMERCIALES.forEach(com => {
    const a = d.asesoras[com];
    if(a.comision_fuera) html += plRow(`Comisión ${com} — Terreno (${a.fuera_cap} cáp.)`, -a.comision_fuera, 'pl-sub');
    if(a.comision_dentro) html += plRow(`Comisión ${com} — OSPIF (${a.dentro_cap} cáp.)`, -a.comision_dentro, 'pl-sub');
    if(!a.comision_fuera && !a.comision_dentro) html += plRow(`Comisión ${com}`, 0, 'pl-sub');
  });
  html += plRow('Total Comisiones', -d.total_comision, 'pl-subtotal');
  html += plRow('Marketing / Publicidad', '— pendiente carga —', 'pl-sub');
  html += plRow('Otros Gastos', '— pendiente carga —', 'pl-sub');
  html += plRow('Total Costos Comerciales', -d.total_comision, 'pl-subtotal');

  const res = d.resultado;
  html += `<tr class="pl-total"><td>RESULTADO COMERCIAL</td><td class="val">${fmtArs(res)}</td></tr>`;

  document.getElementById('costos-pl-body').innerHTML = html;

  // detalle asesoras
  let detHTML = '<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr>'
    +'<th style="text-align:left;padding:8px;border-bottom:1px solid var(--border)">Asesora</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Terreno</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">OSPIF</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Total</th>'
    +'</tr></thead><tbody>';
  COMERCIALES.forEach(com=>{
    const a=d.asesoras[com];
    detHTML+=`<tr><td style="padding:8px;border-bottom:1px solid var(--border)">${com}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${fmtArs(a.comision_fuera)}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${fmtArs(a.comision_dentro)}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border);font-weight:700">${fmtArs(a.total)}</td></tr>`;
  });
  detHTML+='</tbody></table>';
  document.getElementById('costos-asesoras-detalle').innerHTML=detHTML;
}

// ── init ──────────────────────────────────────────────────────────────────────
recalcInforme();
filtrarSeguimiento();
renderCostos();
document.getElementById('period-bar-informe').style.display='flex';
</script>
</body>
</html>
